def restore_durable_v2_sources(raw):
 assert set(raw)==set(BASELINE_SHA256),'exact current source set'
 restored=dict(raw)
 for path,pin in P93_DURABLE_SOURCE_INVERSES.items():
  text=restored[path]
  assert digest(text)==pin['candidate_sha256'],(path,'P93 source pin')
  for current,prior in pin['inverse']:
   assert current and text.count(current)==1,(path,'P93 unique inverse')
   text=text.replace(current,prior,1)
  assert digest(text)==pin['p92_sha256'],(path,'whole P92 restored source')
  restored[path]=text
 return restored

def main():
 p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);a=p.parse_args();r=a.source.resolve()
 raw={k:(r/k).read_bytes().decode('utf-8') for k in BASELINE_SHA256};restored=restore_durable_v2_sources(raw)
 for item in ALIASES:
  path=item['path'];addition=item['addition'];assert restored[path].count(addition)==1,(path,'test alias exactness')
  assert '#[cfg(all(test,' in addition and 'pub(crate) use ' in addition
  restored[path]=restored[path].replace(addition,'',1)
 for item in reversed(EXTRACTIONS):
  path=item['path'];helper='\n'+item['helper'];call=item['replacement']
  assert restored[path].count(helper)==1,(path,'reviewed helper changed')
  assert restored[path].count(call)==1,(path,'reviewed callsite changed')
  restored[path]=restored[path].replace(helper,'',1).replace(call,item['old'],1)
 for path,expected in BASELINE_SHA256.items():assert digest(restored[path])==expected,(path,'original source changed')
 assert len(EXTRACTIONS)==6 and len({x['path'] for x in EXTRACTIONS})==5
 # No genuine Final/owner importer or new public API is hidden in the pure seams.
 for item in EXTRACTIONS:
  helper=item['helper'];assert 'pub(crate) fn project_' in helper
  assert 'FinalV1' not in helper and 'check_current' not in helper and 'Instant::now' not in helper
 print(json.dumps({'baseline':BASELINE,'restored_files':len(BASELINE_SHA256),'pure_projections':6,'candidate_sha256':{p:digest(s) for p,s in raw.items()},'helper_sha256':[digest(x['helper']) for x in EXTRACTIONS],'test_only_alias_files':len(ALIASES),'executed_genuine_constructor':False,'effect_or_transport_qualification':False},sort_keys=True))
if __name__=='__main__':main()
